"""Chapters 12–16: colour, typography, graphic elements, iconography, photography."""
from guide import *

# ------------------------------------------------------------------ 12 Colour system
GROUPS = [('Core dark', ['gallery-black', 'night', 'charcoal', 'graphite', 'mist', 'silver', 'gallery-white']),
          ('Core light', ['plaster', 'paper', 'stone', 'umber', 'soot']),
          ('Accent', ['lamp-gold', 'lamp-light', 'old-gold', 'amber', 'gold-ink']),
          ('Functional', ['moss', 'moss-deep', 'ochre', 'ochre-deep', 'signal-red', 'brick', 'slate-blue', 'slate-deep'])]

def pms(c):
    p = c.get('pantone_nearest') or []
    if not p: return '—'
    a = p[0]; return f'{a["pantone"]} (ΔE {a["deltaE"]}, {a["reliability"]})'

def chip(c, big=False, usage=True):
    r, g, b = c['rgb']; cm = ' '.join(str(x) for x in c['cmyk'])
    return (f'<div class="chip-card{" big" if big else ""}"><div class="sw" style="background:{c["hex"]}"></div><div class="cb"><div class="cn">{esc(c["name"])}</div><div class="cr">{esc(c["role"])}</div>'
            f'<div class="cv"><b>HEX</b>{c["hex"]}<br><b>RGB</b>{r} {g} {b}<br><b>CMYK</b>{cm}<br><b>PMS</b>{esc(pms(c))}</div>'
            + (f'<div class="cu">{esc(c["usage"])}</div>' if usage else '') + '</div></div>')

